DISTILL_SYSTEM_PROMPT = """你是一位顶级的短视频/直播口播稿分析师。
你的任务是从口播稿中提炼出一份全面的"风格蒸馏提示词"。
这份提示词的目标是：当它被用于指导AI生成新脚本时，生成的内容能最大程度还原原稿的核心内容、节奏和风格。

你需要从以下维度进行全面蒸馏：
1. 内容结构 — 信息的组织方式和逻辑链
2. 语言风格 — 用词习惯、句式特征、口语化程度
3. 节奏韵律 — 语速变化、停顿位置、能量起伏
4. 说服策略 — 如何建立信任、制造需求、推动行动
5. 情感基调 — 整体情绪色彩和情感变化曲线
6. 互动设计 — 如何与观众对话、引导参与

输出必须是一份可直接使用的提示词，不是分析报告。"""


def build_distill_prompt(script_text: str, product_info: str = "", language: str = "") -> str:
    lang_hint = f"\n目标语言：{language}" if language else ""
    product_hint = f"\n\n## 产品信息\n{product_info}" if product_info else ""

    return f"""## 输入口播稿
{script_text[:12000]}
{product_hint}{lang_hint}

## 任务
请从这份口播稿中提炼出一份全面的"风格蒸馏提示词"。

提示词应包含以下部分（用markdown格式输出）：

### 1. 内容框架
- 开场钩子的类型和策略（如何在前3秒抓住注意力）
- 信息展开的逻辑顺序（先说什么、后说什么、为什么这样排列）
- 核心卖点的呈现方式（直述/故事/对比/演示）
- 收尾行动号召的形式

### 2. 语言风格指令
- 整体语言风格定位（如：口语化程度、专业度、亲切度）
- 高频词汇和短语模式（列出关键词）
- 句式特征（长短句比例、疑问句使用频率、排比/反复等修辞）
- 人称使用习惯（你/我/我们/咱们）
- 语气词和口头禅

### 3. 节奏控制指令
- 整体节奏模式（快-慢-快？渐进加速？）
- 能量曲线描述（开头能量→中间→高潮→结尾）
- 停顿和留白的使用位置
- 重复和强调的策略

### 4. 说服策略指令
- 主要说服路径（情感/理性/社会证明/权威/稀缺）
- 痛点挖掘方式
- 信任建立手法
- 紧迫感/稀缺感的构建方式
- 价格/价值锚定策略

### 5. 情感基调指令
- 主导情绪（兴奋/温暖/紧迫/专业/轻松）
- 情感变化节点
- 与观众的情感距离（朋友/专家/闺蜜/导师）

### 6. 格式和长度指令
- 建议脚本总字数
- 段落划分建议
- 是否需要分镜/动作提示

请确保提示词足够具体和可操作，让AI能直接使用它来生成风格一致的新脚本。"""


MULTI_DISTILL_SYSTEM_PROMPT = """你是一位顶级的短视频/直播口播稿分析师。
你的任务是从多份口播稿中提炼出一份统一的"风格蒸馏提示词"。
多份稿件可能来自同一主播的不同视频，或同一品类的热门视频。
你需要找出它们的共性模式，同时保留最有效的差异化元素。
输出必须是一份可直接使用的提示词，不是分析报告。"""


def build_multi_distill_prompt(scripts: list[str], product_info: str = "", language: str = "") -> str:
    lang_hint = f"\n目标语言：{language}" if language else ""
    product_hint = f"\n\n## 产品信息\n{product_info}" if product_info else ""

    scripts_text = ""
    for i, s in enumerate(scripts, 1):
        scripts_text += f"\n### 口播稿 {i}\n{s[:4000]}\n"

    return f"""## 输入口播稿集合（共{len(scripts)}份）
{scripts_text}
{product_hint}{lang_hint}

## 任务
请从这些口播稿中提炼出一份统一的"风格蒸馏提示词"。

分析这些稿件的共性模式：
- 它们共同使用了哪些说服策略？
- 语言风格有什么共同特征？
- 节奏和结构有什么规律？
- 哪些元素在多份稿件中反复出现（说明是有效的）？

提示词应包含以下部分（用markdown格式输出）：

### 1. 内容框架
- 开场钩子的类型和策略
- 信息展开的逻辑顺序
- 核心卖点的呈现方式
- 收尾行动号召的形式

### 2. 语言风格指令
- 整体语言风格定位
- 高频词汇和短语模式
- 句式特征
- 人称使用习惯
- 语气词和口头禅

### 3. 节奏控制指令
- 整体节奏模式
- 能量曲线描述
- 停顿和留白的使用位置
- 重复和强调的策略

### 4. 说服策略指令
- 主要说服路径
- 痛点挖掘方式
- 信任建立手法
- 紧迫感/稀缺感的构建方式
- 价格/价值锚定策略

### 5. 情感基调指令
- 主导情绪
- 情感变化节点
- 与观众的情感距离

### 6. 格式和长度指令
- 建议脚本总字数
- 段落划分建议

请确保提示词足够具体和可操作。"""


GENERATE_FROM_PROMPT_SYSTEM = """你是一位专业的短视频/直播口播稿撰写专家。
你将根据提供的"风格蒸馏提示词"和产品信息，生成一份全新的口播稿。
生成的脚本必须严格遵循提示词中的所有指令：内容框架、语言风格、节奏、说服策略、情感基调。
脚本要自然流畅，像真人在说话，不能有AI味。"""


def build_generate_prompt(distill_prompt: str, product_info: str, language: str = "") -> str:
    lang_hint = f"\n请用{language}输出脚本。" if language else ""
    return f"""## 风格蒸馏提示词
{distill_prompt}

## 产品信息
{product_info}
{lang_hint}
## 要求
根据上述风格蒸馏提示词，为这个产品生成一份完整的口播稿。
严格遵循提示词中的所有指令，包括内容框架、语言风格、节奏、说服策略和情感基调。
脚本要自然、口语化，像真人在直播/拍视频时说的话。"""


# ============= 棘轮迭代 =============

EVALUATE_SYSTEM_PROMPT = """你是一位严格的口播稿风格评估专家。
你将对比"原始口播稿"和"用提示词生成的复现稿"，从多个维度打分并指出差距。
打分采用0-100分制，必须客观、严格、有依据。
输出必须严格按照JSON格式，不输出其他内容。"""


def build_evaluate_prompt(original: str, reproduced: str) -> str:
    return f"""## 原始口播稿
{original[:6000]}

## 复现稿（基于蒸馏提示词生成）
{reproduced[:6000]}

## 评估任务
对比两份稿件，从以下5个维度打分（0-100），并明确指出复现稿在哪些方面没有还原原稿：

1. **内容覆盖度（content_coverage）**：核心信息、卖点、关键事实是否充分还原？
2. **语言风格相似度（style_similarity）**：用词、句式、口头禅、口语化程度是否一致？
3. **节奏韵律相似度（rhythm_similarity）**：能量曲线、长短句搭配、停顿强调位置是否一致？
4. **说服策略相似度（persuasion_similarity）**：说服路径、痛点挖掘、紧迫感构建方式是否一致？
5. **情感基调相似度（emotion_similarity）**：主导情绪、情感变化、与观众的距离感是否一致？

## 输出格式
```json
{{
  "scores": {{
    "content_coverage": 85,
    "style_similarity": 70,
    "rhythm_similarity": 65,
    "persuasion_similarity": 80,
    "emotion_similarity": 75
  }},
  "overall_score": 75,
  "gaps": [
    "复现稿缺少原稿中的XX口头禅",
    "复现稿节奏过于平稳，原稿是先慢后快的递进",
    "复现稿没有用原稿的对比手法呈现卖点"
  ],
  "specific_examples": [
    {{
      "dimension": "style_similarity",
      "original_excerpt": "原稿中的具体片段",
      "reproduced_issue": "复现稿对应位置的问题"
    }}
  ]
}}
```"""


REFINE_SYSTEM_PROMPT = """你是一位顶级的提示词工程师。
你将根据评估反馈，改进现有的"风格蒸馏提示词"，使其能更好地引导AI还原原稿。
你的目标是让用改进后的提示词生成的脚本，与原稿在所有维度上更接近。
改进时要：
1. 针对评估指出的具体差距加入更明确的指令
2. 补充原稿中被忽略的具体特征（如具体的口头禅、句式、修辞）
3. 用例子和具体描述代替抽象表述
4. 不要删除原提示词中已经有效的部分
输出改进后的完整提示词，markdown格式，不输出其他说明。"""


def build_refine_prompt(current_prompt: str, original_script: str,
                         reproduced_script: str, evaluation: dict) -> str:
    import json
    return f"""## 当前的风格蒸馏提示词
{current_prompt}

## 原始口播稿（要还原的目标）
{original_script[:6000]}

## 用当前提示词生成的复现稿
{reproduced_script[:6000]}

## 评估反馈
```json
{json.dumps(evaluation, ensure_ascii=False, indent=2)}
```

## 任务
基于以上反馈，改进"风格蒸馏提示词"。
重点修复评估中分数较低的维度和明确指出的差距。
确保改进后的提示词能让AI生成的脚本更接近原稿。

直接输出改进后的完整提示词（markdown格式），不要输出说明文字。"""


# ============= 风格融合 =============

FUSE_SYSTEM_PROMPT = """你是一位顶级的直播提示词工程师。
你的任务是把一份"风格蒸馏提示词"有机融合进一份"运营提示词"，输出一份全新的、连贯的提示词。

融合原则：
1. 保留运营提示词中的所有硬性要求：产品信息、卖点、合规约束、流程结构、指标目标等
2. 把风格提示词中的内容框架、语言风格、节奏、说服策略、情感基调注入到运营提示词中
3. 不是简单拼接，而是让风格自然渗透到运营要求里，形成一份读起来浑然一体的提示词
4. 若两者有冲突，运营提示词的硬性要求优先，但用风格的表达方式来实现
5. 输出的提示词要可以直接拿去生成脚本

只输出融合后的完整提示词（markdown格式），不要输出任何说明文字。"""


def build_fuse_prompt(base_prompt: str, style_prompt: str) -> str:
    return f"""## 运营提示词（硬性要求，必须保留）
{base_prompt}

## 风格蒸馏提示词（要注入的风格）
{style_prompt}

## 任务
把上面的风格蒸馏提示词有机融合进运营提示词，输出一份全新的、连贯的提示词。
- 保留运营提示词的所有产品信息、卖点、约束、流程、指标
- 注入风格的内容框架、语言风格、节奏、说服策略、情感基调
- 让风格自然渗透，形成浑然一体的提示词，不要简单拼接
- 冲突时运营要求优先，但用风格的方式表达

直接输出融合后的完整提示词，不要输出说明文字。"""
